REXCVAR_DEFINE_DOUBLE(ea_texture_lod_bias, 0.0, "Enchanted Arms",
    "Texture detail bias for linear-filtered mipmapped surfaces; 0=original, -0.5=crisp, -1=strong")
    .range(-1.0, 0.0).lifecycle(rex::cvar::Lifecycle::kRequiresRestart);

namespace rex::graphics::d3d12 {

parameters.mip_base_map = mip_base_map;
parameters.detail_eligible = has_mips && !mip_base_map && min_mag_linear &&
                             mip_filter_bilinear_or_trilinear;

// Guest LOD bias stays in the shader. Add an optional host detail bias
// only to filtered mipmapped surfaces; preserve point-sampled UI and base-map fetches.
desc.MipLODBias = parameters.detail_eligible
    ? float(std::clamp(REXCVAR_GET(ea_texture_lod_bias), -1.0, 0.0)) : 0.0f;
